/**
 * City page content — the 93 local-SEO pages, bilingual.
 *
 * Generated by scripts/harvest-city.mjs from data/wp/pages.json (English
 * structure) and data/wp-es/pages.json (Spanish, paired from the rendered /es/
 * HTML). Re-run that script to refresh; do not hand-edit the JSON.
 *
 * The slug lookups below take the LAST path segment, because both routes are
 * single-segment (`/naranjo-alajuela/`, `/es/naranjo-alajuela/`) and Next.js
 * hands the route a bare slug rather than a full path.
 */
import cityData from '@/data/pages/city.json';

const segment = (path) => path.replace(/^\/|\/$/g, '').split('/').pop();

const BY_EN = new Map(cityData.pages.map((p) => [segment(p.en), p]));
const BY_ES = new Map(cityData.pages.filter((p) => p.es).map((p) => [segment(p.es), p]));

export const pages = cityData.pages;
export const harvestedAt = cityData.harvestedAt;

export const byEnglishSlug = (slug) => BY_EN.get(slug) ?? null;
export const bySpanishSlug = (slug) => BY_ES.get(slug) ?? null;

export const englishParams = () => [...BY_EN.keys()].map((slug) => ({ slug }));
export const spanishParams = () => [...BY_ES.keys()].map((slug) => ({ slug }));

export default cityData;
